// الفصل الأوّل: القيمةُ المنزليّة
import { AR, fmt, rnd, pick, shuf } from './mathkit.js';
import { $, $$, tbl, num, lst, mcq, ch, open, fld, star } from './engine.js';
import { fr } from './algebra.js';
import { KB, T2, A, MX, r10, placeQ, pvTable, words, decWords, wordQ, expQ, expHTML, cmpS, cmpTool, gridSVG, cubeSVG, decTool, pvTool, nlSVG, gcTool, gcQ, sortedStr } from './kit5.js';

const big = s => `<b class="big">${A(s)}</b>`;
const decQ = (tag, n, d, o = {}) => num(tag, o.text || `اكتبِ الكسرَ ${fr(n, d)} على صورةِ كسرٍ عشريّ:`, r10(n / d), { skill: 'dfrac', html: o.grid === false ? '' : d === 1000 ? cubeSVG(Math.min(n, 100)) : gridSVG(d === 10 ? n : n, d), htmlOpt: true, sol: [`${fr(n, d)} = ${A((n / d).toFixed(String(d).length - 1))}` + (d === 10 ? ' (رقمٌ واحدٌ عن يمينِ الفاصلة)' : d === 100 ? ' (رقمان عن يمينِ الفاصلة)' : ' (ثلاثةُ أرقامٍ عن يمينِ الفاصلة)')], ...o });
const stdQ = (tag, text, v, o = {}) => num(tag, text, v, { skill: 'std', sol: [`الصيغةُ القياسيّة: ${A(String(v))}`], ...o });
const ordQ = (tag, text, arr, o = {}) => lst(tag, text, sortedStr(arr, o.desc).map(Number), { skill: 'order', sol: [(o.desc ? 'من الأكبرِ إلى الأصغر: ' : 'من الأصغرِ إلى الأكبر: ') + sortedStr(arr, o.desc).map(A).join('، ')], hints: ['اكتبِ الأعدادَ رأسيًّا بحيثُ تتحاذى المنازل (والفواصلُ العشريّة).', 'أضفْ أصفارًا عن يمينِ الكسورِ العشريّةِ لتتساوى المنازل، ثم قارنْ من اليسار.'], ...o });
const sym = (tag, text, a, s, b) => ch(tag, text, [`${A(a)} &lt; ${A(b)}`, `${A(a)} &gt; ${A(b)}`, `${A(a)} = ${A(b)}`], s === '<' ? 0 : s === '>' ? 1 : 2);

/* ═════════ المولّدات ═════════ */
const randNum = (L, dmin = 5) => { const n = rnd(dmin + L, Math.min(12, 7 + 2 * L)); return String(rnd(1, 9)) + Array.from({ length: n - 1 }, () => Math.random() < .25 ? 0 : rnd(0, 9)).join(''); };
const randDec = L => { const w = String(rnd(0, L ? 99 : 9)), f = Array.from({ length: rnd(1, 3) }, () => rnd(0, 9)).join(''); return w + '.' + (f.endsWith('0') ? f.slice(0, -1) + rnd(1, 9) : f); };
const G = {
  place: L => { const s = randNum(L); const ks = [...s].map((c, i) => i).filter(i => s[i] !== '0'); return placeQ('', s, pick(ks)); },
  std: L => { const n = +randNum(L, 4); return stdQ('', `اكتبْ بالصيغةِ القياسيّة: ${words(n)}`, n); },
  exp: L => expQ('', randNum(L, 4)),
  words: L => wordQ('', randNum(L, 4)),
  cmp: L => { const s = randNum(L, 4); const t = [...s]; const k = rnd(1, s.length - 1); t[k] = String((+t[k] + rnd(1, 8)) % 10); return Math.random() < .5 ? cmpS('', s, t.join('')) : cmpS('', t.join(''), s); },
  dfrac: L => { const d = pick([10, 100, 1000]); return decQ('', rnd(1, d - 1), d, { grid: d !== 1000 }); },
  dplace: L => { const s = randDec(L); const ks = [...s].map((c, i) => i).filter(i => s[i] !== '.' && s[i] !== '0'); return placeQ('', s, pick(ks)); },
  dwords: L => wordQ('', randDec(L)),
  dcmp: L => { const a = randDec(L); let b = pick([a + '0', String(r10(parseFloat(a) + pick([0.1, 0.01, 0.001, -0.01]), 3)), a.slice(0, -1) || a]); if (parseFloat(b) < 0) b = a; return cmpS('', a, b); },
  order: L => { const base = rnd(1, 30); const arr = [...new Set(Array.from({ length: 4 }, () => String(r10(base + rnd(0, L ? 120 : 30) / pick([10, 100]), 2))))]; return ordQ('', `رتّبِ الأعدادَ من الأصغرِ إلى الأكبر: ${shuf(arr).map(A).join('، ')}`, arr); },
  gc: L => { const P = pick([{ A: 'جمالٌ بسنامين', B: 'جمالٌ بسنامٍ واحد', a: 2, b: 1, u: 'جملًا', t: 'سنامًا' }, { A: 'دراجاتٌ بثلاث عجلات', B: 'دراجاتٌ بعجلتين', a: 3, b: 2, u: 'درّاجة', t: 'عجلة' }, { A: 'أوراقٌ من فئةِ ١٠ ريالات', B: 'أوراقٌ من فئةِ ٥ ريالات', a: 10, b: 5, u: 'ورقة', t: 'ريالًا' }]);
    const n = rnd(8, 20 + 10 * L), x = rnd(1, n - 1), T = P.a * x + P.b * (n - x);
    return num('', `استعملْ خطّةَ التخمينِ والتحقّق: المجموعُ ${AR(n)} ${P.u}، والإجماليُّ ${AR(T)} ${P.t}. إذا كانت الأنواعُ: ${P.A} و${P.B}، فكم عددُ ${P.A}؟`, x, { skill: 'gc', sol: [`${AR(P.a)} × ${AR(x)} + ${AR(P.b)} × ${AR(n - x)} = ${AR(T)} ✓`], mount: el => gcTool(el, { n, T, a: P.a, b: P.b, A: P.A, B: P.B }) }); },
};
const GN = { place: 'القيمة المنزلية', std: 'الصيغة القياسية', exp: 'الصيغة التحليلية', words: 'الصيغة اللفظية', cmp: 'مقارنة الأعداد', dfrac: 'كتابة الكسر العشري', dplace: 'منازل الكسور العشرية', dwords: 'قراءة الكسور العشرية', dcmp: 'مقارنة الكسور العشرية', order: 'الترتيب', gc: 'التخمين والتحقق' };

