/* ═════════ هيّا بنا نلعب: لعبةُ الكسورِ العشريّة ═════════ */
function decGame(el) {
  let me = [], cpu = [], score = [0, 0], round = 1, spinning = false;
  const draw = (msg = '') => { const card = (a, who) => `<div class="dgcard"><small>${who}</small><div>${[0, 1, 2, 3].map(i => `${i === 1 ? '<b class="dot">,</b>' : ''}<button class="slot" data-i="${i}" ${who === 'أنت' && a[i] === undefined && cur !== null ? '' : 'disabled'}>${a[i] === undefined ? '' : AR(a[i])}</button>`).join('')}</div></div>`;
    el.innerHTML = `<div class="meta">الجولة ${AR(round)} من ٥ · النقاط: أنت ${AR(score[0])} – الحاسوب ${AR(score[1])}</div><div class="row c">${card(me, 'أنت')}${card(cpu, 'الحاسوب')}</div><div class="row c"><button class="btn" data-a="spin" ${cur !== null || spinning ? 'disabled' : ''}>🎡 أدرِ المؤشّر</button><b class="dgnum">${cur === null ? '' : AR(cur)}</b></div><div class="meta">${msg || (cur !== null ? 'اخترْ فراغًا في بطاقتِك لتضعَ فيه الرقم.' : 'أدرِ المؤشّرَ لتحصلَ على رقم.')}</div>`;
    const sp = $('[data-a="spin"]', el); if (sp) sp.onclick = spin;
    $$('.slot:not([disabled])', el).forEach(b => b.onclick = () => place(+b.dataset.i)); };
  let cur = null;
  const spin = () => { spinning = true; let k = 0; const iv = setInterval(() => { cur = rnd(0, 9); $('.dgnum', el) && ($('.dgnum', el).textContent = AR(cur)); if (++k > 10) { clearInterval(iv); spinning = false; draw(); } }, 70); };
  const place = i => { me[i] = cur; // الحاسوب: يضعُ الأرقامَ الكبيرةَ في المنازلِ الكبرى
    const free = [0, 1, 2, 3].filter(j => cpu[j] === undefined); const j = cur >= 5 ? free[0] : free[free.length - 1]; cpu[j] = cur; cur = null;
    if (me.filter(x => x !== undefined).length === 4) { const a = +(me[0] + '' + me[1] + '.' + me[2] + me[3]) , b = +(cpu[0] + '' + cpu[1] + '.' + cpu[2] + cpu[3]); const res = a > b ? 'فزتَ بهذه الجولة! 🎉' : a < b ? 'فازَ الحاسوبُ بهذه الجولة.' : 'تعادل!'; if (a > b) { score[0]++; star(1); } else if (b > a) score[1]++;
      const msg = `بطاقتُك ${AR(a.toFixed(2))} وبطاقةُ الحاسوب ${AR(b.toFixed(2))}: ${res}`; if (round >= 5) { el.innerHTML = `<div class="keybox">${msg}<br><b>انتهتِ اللعبة: ${score[0] > score[1] ? 'أنتَ الفائز 🏆' : score[0] < score[1] ? 'الفائزُ الحاسوب' : 'تعادل'}</b></div><button class="btn">🔁 العبْ مجدّدًا</button>`; $('button', el).onclick = () => { me = []; cpu = []; score = [0, 0]; round = 1; draw(); }; return; }
      round++; me = []; cpu = []; draw(msg); return; }
    draw(); };
  draw();
}
